outputs = { nixpkgs, home-manager, nix-darwin, sops-nix, walker, nixgl, explore-mcp, drovr, hunk, mattpocock-skills, zen-browser, ssh-oidc, ... }:
let
  mkHome = system: machine: home-manager.lib.homeManagerConfiguration {
    pkgs = nixpkgs.legacyPackages.${system};
    extraSpecialArgs = {
      inherit sops-nix walker nixgl explore-mcp drovr hunk mattpocock-skills zen-browser machine;
      inherit system;
    };
    modules = [ ./home.nix ];
  };
  linuxHome = mkHome "x86_64-linux";
in {
  homeConfigurations.utsuho = linuxHome {
    hostname = "utsuho";
    gui = true;
    gpu = "amd";
  };
  homeConfigurations.kyuusaku = linuxHome {
    hostname = "kyuusaku";
    gui = false;
    homeDir = "/local/mnt/workspace/kyuusaku";
  };
  homeConfigurations.setsuna = linuxHome {
    hostname = "setsuna";
    gui = true;
  };
  homeConfigurations.shiori = linuxHome {
    hostname = "shiori";
    gui = true;
  };
  homeConfigurations.fujiwara = linuxHome {
    hostname = "fujiwara";
    # Headless: the box has an HDMI display wired up, but no graphical session
    # has run on it since Jun 2025. Dropping the desktop stack (hyprland,
    # waybar, walker, kanshi, portals) rather than leaving units to fail at
    # every activation. Flip back to true if it becomes a workstation again.
    gui = false;
    gpu = "amd";
  };
  homeConfigurations.mari = mkHome "aarch64-darwin" {
    hostname = "mari";
    gui = true;
  };

  darwinConfigurations.mari = nix-darwin.lib.darwinSystem {
    system = "aarch64-darwin";
    modules = [
      sops-nix.darwinModules.sops
      ssh-oidc.darwinModules.default

input.old_string:
      echo "  no network. Continuing; nothing below needs these packages." >&2
    }
  fi
  ;;
*)

